#include <iostream>
using namespace std;

int main() {
    string input_sentence = "Every dot is a person, and every line represents a volume of calls between the people.";

    // Split the sentence into words
    vector<string> tokens(input_sentence.begin(), input_sentence.end());

    // Remove any punctuation from each token
    for (auto& token : tokens) {
        if (!isalnum(token[0])) {
            token = "";
        } else {
            token +='';
        }
    }

    // Translate the sentence into Spanish
    string translation = "";
    int counter = 1;
    for (const auto& token : tokens) {
        switch (counter % 2 == 0? toupper(token[0]) : lowercase(token[0])) {
            case 'A':
                translation += "un";
                break;
            case 'E':
                translation += "una";
                break;
            default:
                translation += token;
                break;
        }

        counter++;
    }

    cout << "Cadena original: " << input_sentence << endl;
    cout << "Translado al español: " << translation << endl;

    return 0;
}
