import re
from collections import Counter

def main():
    # Prompt user for input string
    try:
        text = input("Enter a sentence (English): ")

        # Remove all punctuation marks from the string
        text = "".join(ch for ch in text if ch not in ".!,;")

        # Split the string into individual words using whitespace as delimiter
        words = text.split()

        # Count how many times each word appears in the list of words
        frequency_dict = {}
        for word in words:
            count = 0
            for char in word:
                if char in frequency_dict:
                    count += frequency_dict[char]
                else:
                    frequency_dict[char] = 1
            if len(word) > 2:
                if word[:-2].lower() in frequency_dict:
                    frequency_dict[word[:-2].lower()] += 1
                elif word[-2:] in frequency_dict:
                    frequency_dict[word[-2:]].append(count+1)
            else:
                if word[:len(word)] in frequency_dict:
                    frequency_dict[word[:len(word)]]+=1
                elif word[-len(word):] in frequency_dict:
                    frequency_dict[word[-len(word):]]+=1

        # Sort the dictionary by key (in descending order), with most frequent first
        sorted_frequency_dict = sorted(frequency_dict.items(), key=lambda x: -x[1], reverse=True)

        # Find the total number of occurrences of each word in the list of words
        num_occurrences = []
        for word, freq in sorted_frequency_dict:
            num_occurrences.append((freq, word))

        # Print out the results
        print("Total Number of Occurrences:", sum([item[1] for item in num_occurrences]))
        print("\nTop N Words (Frequently Used First)")
        for n, (word, freq) in enumerate(sorted_frequency_dict[:5]):
            print("%d. %s (%d times)" % (n + 1, word, freq))
    except Exception as e:
        print(e)

if __name__ == '__main__':
    main()
